constexpr int factorial(int n) {
  return (n == 0) ? 1 : n * factorial(n - 1);
}

template <int N>
constexpr int powerOf2() {
  return 1 << N; 
}

int main() {
  constexpr int fact5 = factorial(5); // Calculated at compile time
  constexpr int pow2_10 = powerOf2<10>(); // Calculated at compile time
  std::cout << "Factorial of 5: " << fact5 << std::endl; 
  std::cout << "2 to the power of 10: " << pow2_10 << std::endl;
  return 0;
}
